type Faq = { question: string; answer: string };

/** src/lib/column-shared.ts の ColumnTranslation と同形 */
type Translation = {
  title: string;
  excerpt: string;
  content: string;
  category?: string;
  keywords?: string[];
  tags?: string[];
  author?: { name: string; title: string };
  faq?: Faq[];
};

const LOCALES = ["en", "zh-tw", "zh"] as const;
type Locale = (typeof LOCALES)[number];

type SeedColumn = {
  business: "labor";
  slug: string;
  title: string;
  date: string;
  category: string;
  excerpt: string;
  content: string;
  status: "published";
  author: { name: string; title: string };
  keywords: string[];
  tags: string[];
  locales: string[];
  faq: Faq[];
  translations?: Partial<Record<Locale, Translation>>;
};

